1	/**
2	 * Supabase Adapter for Gravito
3	 * 
4	 * This adapter wraps supabase-db.ts functions to provide camelCase property names
5	 * that are compatible with the existing routers.ts code.
6	 */
7	
8	import * as supabaseDb from './supabase-db';
9	import { generalLog } from './_core/logger';
10	
11	// ============ Type Converters ============
12	
13	function snakeToCamel(str: string): string {
14	  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
15	}
16	
17	function convertKeysToCamel<T extends Record<string, unknown>>(obj: T): Record<string, unknown> {
18	  const result: Record<string, unknown> = {};
19	  for (const key in obj) {
20	    if (Object.prototype.hasOwnProperty.call(obj, key)) {
21	      result[snakeToCamel(key)] = obj[key];
22	    }
23	  }
24	  return result;
25	}
26	
27	// ============ User Types (camelCase) ============
28	
29	export interface User {
30	  id: number;
31	  openId: string;
32	  name: string | null;
33	  email: string | null;
34	  loginMethod: string | null;
35	  passwordHash: string | null;
36	  role: 'admin' | 'user';
37	  lastSignedIn: string | null;
38	  createdAt: string;
39	  updatedAt: string;
40	}
41	
42	export interface ApiKey {
43	  id: number;
44	  userId: number;
45	  keyHash: string;
46	  keyPrefix: string;
47	  name: string;
48	  isActive: boolean;
49	  lastUsedAt: string | null;
50	  createdAt: string;
51	}
52	
53	export interface Subscription {
54	  id: number;
55	  userId: number;
56	  plan: string;
57	  stripeCustomerId: string | null;
58	  stripeSubscriptionId: string | null;
59	  status: string;
60	  currentPeriodStart: string | null;
61	  currentPeriodEnd: string | null;
62	  cancelAtPeriodEnd: boolean;
63	  createdAt: string;
64	  updatedAt: string;
65	}
66	
67	export interface ApiUsage {
68	  id: number;
69	  userId: number;
70	  apiKeyId: number | null;
71	  endpoint: string;
72	  callCount: number;
73	  date: string;
74	  createdAt: string;
75	}
76	
77	export interface EmotionalHistory {
78	  id: number;
79	  userId: number;
80	  externalUserId: string | null;
81	  emotion: string;
82	  valence: number;
83	  arousal: number;
84	  escalationRisk: 'low' | 'medium' | 'high';
85	  context: string | null;
86	  conversationId: string | null;
87	  createdAt: string;
88	}
89	
90	export interface EmotionalPattern {
91	  id: number;
92	  userId: number;
93	  externalUserId: string | null;
94	  patternType: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
95	  description: string;
96	  triggers: string | null;
97	  frequency: number;
98	  lastOccurrence: string;
99	  recommendedApproach: string | null;
100	  createdAt: string;
101	  updatedAt: string;
102	}
103	
104	export interface BillingHistory {
105	  id: number;
106	  userId: number;
107	  stripeInvoiceId: string | null;
108	  stripePaymentIntentId: string | null;
109	  amount: number;
