111	  status: string;
112	  description: string | null;
113	  createdAt: string;
114	}
115	
116	// ============ User Functions ============
117	
118	export async function upsertUser(userData: {
119	  openId: string;
120	  name?: string | null;
121	  email?: string | null;
122	  loginMethod?: string | null;
123	  passwordHash?: string | null;
124	  role?: 'admin' | 'user';
125	  lastSignedIn?: Date;
126	}): Promise<void> {
127	  await supabaseDb.upsertUser(userData);
128	}
129	
130	export async function getUserByOpenId(openId: string): Promise<User | null> {
131	  const user = await supabaseDb.getUserByOpenId(openId);
132	  if (!user) return null;
133	  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
134	}
135	
136	export async function getUserById(id: number): Promise<User | null> {
137	  const user = await supabaseDb.getUserById(id);
138	  if (!user) return null;
139	  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
140	}
141	
142	export async function getUserByEmail(email: string): Promise<User | null> {
143	  const user = await supabaseDb.getUserByEmail(email);
144	  if (!user) return null;
145	  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
146	}
147	
148	// ============ API Key Functions ============
149	
150	export async function createApiKey(userId: number, name?: string): Promise<{ key: string; prefix: string }> {
151	  const result = await supabaseDb.createApiKey(userId, name);
152	  if (!result) {
153	    throw new Error('Failed to create API key');
154	  }
155	  return result;
156	}
157	
158	export async function getApiKeysByUserId(userId: number): Promise<Partial<ApiKey>[]> {
159	  const keys = await supabaseDb.getApiKeysByUserId(userId);
160	  return keys.map(k => convertKeysToCamel(k as unknown as Record<string, unknown>)) as Partial<ApiKey>[];
161	}
162	
163	export async function validateApiKey(key: string): Promise<ApiKey | null> {
164	  const apiKey = await supabaseDb.validateApiKey(key);
165	  if (!apiKey) return null;
166	  return convertKeysToCamel(apiKey as unknown as Record<string, unknown>) as unknown as ApiKey;
167	}
168	
169	export async function deleteApiKey(userId: number, keyId: number): Promise<boolean> {
170	  return supabaseDb.deleteApiKey(userId, keyId);
171	}
172	
173	export async function regenerateApiKey(userId: number, keyId: number): Promise<{ key: string; prefix: string } | null> {
174	  return supabaseDb.regenerateApiKey(userId, keyId);
175	}
176	
177	// ============ Subscription Functions ============
178	
179	export async function getSubscriptionByUserId(userId: number): Promise<Subscription | null> {
180	  const sub = await supabaseDb.getSubscriptionByUserId(userId);
181	  if (!sub) return null;
182	  return convertKeysToCamel(sub as unknown as Record<string, unknown>) as unknown as Subscription;
183	}
184	
185	export async function createOrUpdateSubscription(subData: {
186	  userId: number;
187	  plan: string;
188	  stripeCustomerId?: string | null;
189	  stripeSubscriptionId?: string | null;
190	  status?: string;
191	  currentPeriodStart?: Date | null;
192	  currentPeriodEnd?: Date | null;
193	  cancelAtPeriodEnd?: boolean;
194	}): Promise<boolean> {
195	  return supabaseDb.createOrUpdateSubscription(subData);
196	}
197	
198	// ============ Usage Functions ============
199	
200	export async function recordApiUsage(userId: number, apiKeyId: number | null, endpoint: string): Promise<void> {
201	  return supabaseDb.recordApiUsage(userId, apiKeyId, endpoint);
202	}
203	
204	export async function getUsageByUserId(userId: number, days: number = 30): Promise<ApiUsage[]> {
205	  const usage = await supabaseDb.getUsageByUserId(userId, days);
206	  return usage.map(u => convertKeysToCamel(u as unknown as Record<string, unknown>) as unknown as ApiUsage);
207	}
208	
209	export async function getTotalUsageThisMonth(userId: number): Promise<number> {
210	  return supabaseDb.getTotalUsageThisMonth(userId);
211	}
212	
213	export async function getUsageBreakdownByEndpoint(userId: number, days: number = 30) {
214	  const dbModule = await import('./db');
215	  return dbModule.getUsageBreakdownByEndpoint(userId, days);
216	}
217	
218	// ============ Billing Functions ============
219	
220	export async function getBillingHistory(userId: number): Promise<BillingHistory[]> {
221	  const history = await supabaseDb.getBillingHistory(userId);
222	  return history.map(h => convertKeysToCamel(h as unknown as Record<string, unknown>) as unknown as BillingHistory);
223	}
224	
225	export async function recordBillingEvent(billingData: {
226	  userId: number;
227	  stripeInvoiceId?: string | null;
228	  stripePaymentIntentId?: string | null;
229	  amount: number;
230	  currency?: string;
231	  status: string;
232	  description?: string | null;
233	}): Promise<boolean> {
234	  return supabaseDb.addBillingRecord(billingData);
235	}
236	
237	// ============ Rate Limiting ============
238	
239	export async function checkRateLimit(
240	  userId: number,
241	  plan: string
