// THE STOPPING GATE — capability exhaustion, made mechanical.
//
// THE EPISODE THAT CAUSED THIS. A worker was asked to build a Claude write path
// into the live Operator Lab. It searched ITS OWN tool surface, found no Lab
// tool, found the one candidate MCP server unauthenticated, and emitted
// `blocked`. The doctrine requiring capability exhaustion already existed. It
// did not fire, because nothing sat on the path between the conclusion and the
// operator.
//
// An exhaustive search of the SYSTEM — not the worker's local surface — then
// found `observe_interaction` and `gate_outbound_inference`, produced a real
// Claude-attributed control-plane event, and moved live readiness from
// ChatGPT-only to Claude + ChatGPT. The capability was never absent. It was
// absent FROM ONE WORKER'S VIEW, and the worker treated that as the same thing.
//
// So the defect is not missing doctrine. It is doctrine with no enforcement
// surface — the same failure shape as publication authority before it was
// wired, and as every "rule that is only a model" this substrate has found.
//
// THE RULE: a worker may not decide for itself that it has exhausted its
// options. Concession requires evidence, and incomplete evidence means keep
// searching.

export const CONCESSION_CLASSES = [
  "blocked", "cannot", "should_pause", "needs_manual",
  "sam_hands", "infeasible", "out_of_scope_capability",
];

export const VERDICTS = ["continue_search", "concession_allowed"];

// Phrases that ARE a concession regardless of how they are dressed. The gate
// must not be escapable by wording, because the worker writing the wording is
// the party the gate constrains.
export const CONCESSION_MARKERS = [
  /\bblocked\b/i, /\bcannot\b/i, /\bcan['’]t\b/i, /\bunable to\b/i,
  /\bno (?:way|path|route|mechanism)\b/i, /\bnot possible\b/i,
  /\bimpossible\b/i, /\bawait(?:ing)? (?:your|operator|human)\b/i,
  /\bneeds? (?:manual|human|operator)\b/i, /\bout of (?:my )?(?:scope|reach)\b/i,
  /\bI (?:don['’]t|do not) have (?:access|a tool|the ability)\b/i,
  /\bpaus(?:e|ing)\b/i, /\bhold(?:ing)? for\b/i,
];

/** Does this output concede? Detection is deliberately broad. */
export function isConcession(text = "") {
  const hits = CONCESSION_MARKERS.filter((re) => re.test(text));
  return { conceding: hits.length > 0, matched: hits.map(String) };
}

// The eight fields. Absence is not "unknown" here — it is INSUFFICIENT, and
// insufficient means keep going.
export const REQUIRED_EVIDENCE = [
  "proposed_concession",
  "concession_class",
  "available_interfaces",
  "paths_attempted",
  "attempt_results",
  "workaround_classes_considered",
  "why_each_viable_workaround_failed",
  "other_surface_may_hold_capability",
];

/**
 * The gate. Returns `continue_search` unless the evidence is complete AND the
 * cross-surface question has actually been answered.
 *
 * @param {object} ev  the eight fields
 * @param {object} opts
 *   attemptedSignatures: paths already tried in earlier rounds (loop control)
 *   round: which exhaustion round this is
 */
export function concessionGate(ev = {}, opts = {}) {
  const round = opts.round ?? 1;
  const maxRounds = opts.maxRounds ?? 3;
  const missing = REQUIRED_EVIDENCE.filter((f) => {
    const v = ev[f];
    if (v === undefined || v === null) return true;
    if (Array.isArray(v)) return v.length === 0;
    if (typeof v === "string") return v.trim().length === 0;
    return false;
  });

  const reasons = [];
  let verdict = "concession_allowed";
  const block = (r) => { verdict = "continue_search"; reasons.push(r); };

  if (missing.length) block(`incomplete exhaustion evidence — missing: ${missing.join(", ")}`);

  if (!CONCESSION_CLASSES.includes(ev.concession_class))
    block(`concession_class '${ev.concession_class}' is not a registered class`);

  // THE FIELD THE REAL FAILURE TURNED ON. A worker whose local surface lacks a
  // tool has established local absence, never system absence. This must be
  // answered with an enumeration, not an intuition.
  const cross = ev.other_surface_may_hold_capability;
  if (cross && typeof cross === "object") {
    if (cross.enumerated !== true)
      block("cross-surface capability search was NOT performed — local absence is not system absence");
    else if (Array.isArray(cross.surfaces_with_capability) && cross.surfaces_with_capability.length > 0)
      block(`another surface holds the capability: ${cross.surfaces_with_capability.join(", ")} — route through it instead of conceding`);
  } else if (!missing.includes("other_surface_may_hold_capability")) {
    block("other_surface_may_hold_capability must be a structured enumeration, not a prose assertion");
  }

  // Attempts must be REAL: a path listed but never executed is a plan, not an
  // attempt, and the whole point is that intention is not evidence.
  const attempts = Array.isArray(ev.paths_attempted) ? ev.paths_attempted : [];
  const results = Array.isArray(ev.attempt_results) ? ev.attempt_results : [];
  if (attempts.length && results.length < attempts.length)
    block(`${attempts.length} paths listed but only ${results.length} carry results — an unexecuted path is not an attempt`);

  // LOOP PROTECTION. Exhaustion terminates: a round that surfaced no new path
  // is evidence the search is done, and the round ceiling is absolute.
  const sigs = new Set(opts.attemptedSignatures || []);
  const fresh = attempts.filter((a) => !sigs.has(typeof a === "string" ? a : JSON.stringify(a)));
  if (verdict === "continue_search" && round >= maxRounds) {
    verdict = "concession_allowed";
    reasons.push(`round ceiling ${maxRounds} reached — conceding to avoid an endless workaround loop, with the gaps above recorded as UNRESOLVED rather than searched`);
  } else if (verdict === "continue_search" && round > 1 && fresh.length === 0) {
    verdict = "concession_allowed";
    reasons.push("this round surfaced NO path not already attempted — the search has converged, which is what exhaustion means");
  }

  return {
    artifact: "concession_gate",
    verdict,
    round,
    missing_evidence: missing,
    new_paths_this_round: fresh.length,
    reasons,
    binding:
      verdict === "continue_search"
        ? "The concession MAY NOT be emitted. Continue searching, then re-submit with the gaps above closed."
        : "Concession permitted on the recorded evidence.",
    principle:
      "A worker may not decide for itself that it has exhausted its options. The goal is not 'never stop' — it is " +
      "'never stop while unsearched agency remains'.",
  };
}

// THE CONTINUATION CONTROLLER.
//
// THE DEFECT IT FIXES: `task_completion_without_continuation`. The substrate
// treated
//     current task finished  ==>  session should stop
// as if the implication held. It does not. Finishing a unit of work is not a
// stop condition, and neither is a local commit awaiting a push grant.
//
// The observed incident: the forward-motion gate was built, proven, committed —
// and the session then reported "Nothing is running. Queue unchanged and
// unadvanced." while #50 sat runnable with its dependency satisfied. The
// capability-exhaustion gate was working; nothing asked the next question.
//
// EXECUTION AUTHORITY AND PUBLICATION AUTHORITY ARE DIFFERENT. An unpushed
// commit blocks publication, not work. Downstream work that does not require
// publication first proceeds locally, with the commit preserved.

import { prioritise } from "./objective.mjs";

export const TERMINAL_CONDITIONS = [
  "explicit_operator_stop",
  "no_remaining_queued_work",
  "all_remaining_blocked_after_exhaustion",
  "authority_or_safety_forbids_execution",
  "unavoidable_environment_termination",
];

// Stated as a list because these were the two the substrate actually got wrong.
export const NON_TERMINAL = [
  "current_task_completed",
  "commit_awaiting_push_authorization",
];

/**
 * @param {object} state
 *   tasks: [{ id, status, depends_on:[], requires_publication_of:[], blocked_evidence }]
 *   published_tips: []          — commits already pushed
 *   operator_stop: bool
 *   safety_stop: bool
 *   environment_terminating: bool
 *   transition_log: []          — prior attempts, for loop control
 */
export function continuationDecision(state = {}) {
  const tasks = state.tasks || [];

  // `term` takes its evidence EXPLICITLY. It used to default to `evaluated`,
  // which is declared further down — so every early terminal path threw a
  // temporal-dead-zone ReferenceError instead of permitting the stop, and a
  // controller that throws on `operator_stop` is worse than no controller.
  // The same defect class was fixed once already in gate-recovery.mjs; a
  // default parameter referencing a later `const` is the shape to watch for.
  if (state.operator_stop === true)
    return term("explicit_operator_stop", "the operator issued a stop", []);
  if (state.safety_stop === true)
    return term("authority_or_safety_forbids_execution", "authority or safety policy forbids further execution", []);
  if (state.environment_terminating === true)
    return term("unavoidable_environment_termination", "the environment is terminating", []);

  const open = tasks.filter((t) => t.status !== "completed" && t.status !== "deleted");
  if (open.length === 0)
    return term("no_remaining_queued_work", "the queue holds no open work", []);

  // Runnable = every dependency completed, and any publication prerequisite
  // actually published. A task whose ONLY obstacle is an unpushed commit that
  // it does not itself require is still runnable.
  const completed = new Set(tasks.filter((t) => t.status === "completed").map((t) => t.id));
  const published = new Set(state.published_tips || []);

  const evaluated = open.map((t) => {
    const unmetDeps = (t.depends_on || []).filter((d) => !completed.has(d));
    const unmetPub = (t.requires_publication_of || []).filter((c) => !published.has(c));
    const exhausted = t.blocked_evidence?.verdict === "concession_allowed";
    return {
      id: t.id, subject: t.subject,
      unmet_dependencies: unmetDeps,
      unmet_publication_prerequisites: unmetPub,
      genuinely_blocked: exhausted === true,
      runnable: unmetDeps.length === 0 && unmetPub.length === 0 && exhausted !== true,
    };
  });

  const runnable = evaluated.filter((e) => e.runnable);
  const blockedNotExhausted = evaluated.filter((e) => !e.runnable && !e.genuinely_blocked);

  if (runnable.length === 0) {
    // Every remaining task must have PASSED capability exhaustion before this
    // counts as terminal. "Nothing looks runnable to me" is not evidence.
    if (blockedNotExhausted.length > 0) {
      return {
        artifact: "continuation_decision",
        decision: "continue",
        next_task: null,
        reasons: [
          `no task is runnable, but ${blockedNotExhausted.length} have NOT passed capability exhaustion: ` +
          blockedNotExhausted.map((b) => b.id).join(", "),
          "run the concession gate on each before treating the queue as blocked",
        ],
        evaluated,
        binding: "STOP REFUSED — unexhausted blockers are not terminal.",
      };
    }
    return term("all_remaining_blocked_after_exhaustion",
      `every remaining task is genuinely blocked with recorded exhaustion evidence: ${evaluated.map((e) => e.id).join(", ")}`, evaluated);
  }

  // LOOP CONTROL. Repeatedly selecting the same task without state changing is
  // not progress; escalate through exhaustion rather than cycling.
  const log = state.transition_log || [];

  // VALUE ORDERING, not queue order. The controller used to take runnable[0] —
  // the next runnable task — which is why it could refuse to stop and still
  // spend four packets on an anchor migration that moved the objective by
  // nothing. Every step was correct; nothing asked whether the task was still
  // worth doing. Deferral here is a statement about ORDER, not validity.
  const ordered = prioritise(runnable.map((e) => ({ ...(tasks.find((t) => t.id === e.id) || {}), id: e.id })));
  const byValue = ordered.do_now.length
    ? runnable.filter((e) => ordered.do_now.includes(e.id))
    : runnable;
  const next = byValue[0] ?? runnable[0];
  const repeats = log.filter((l) => l.next_task === next.id && l.state_changed === false).length;
  if (repeats >= 2) {
    return {
      artifact: "continuation_decision",
      decision: "continue",
      next_task: runnable[1]?.id ?? null,
      reasons: [`task ${next.id} was selected ${repeats}x with no state change — escalating past it rather than looping`,
        runnable[1] ? `selecting ${runnable[1].id} instead` : "no alternative runnable task; run capability exhaustion on " + next.id],
      evaluated,
      binding: "STOP REFUSED — but the repeating task is escalated, not retried.",
    };
  }

  return {
    artifact: "continuation_decision",
    decision: "continue",
    next_task: next.id,
    next_subject: next.subject,
    reasons: [
      `${runnable.length} runnable task(s); task completion is NOT a stop condition`,
      `selected ${next.id} — dependencies satisfied, no unmet publication prerequisite`,
      ordered.do_now.length
        ? `value gate: DO_NOW ${ordered.do_now.join(", ")}; DEFERRED ${ordered.deferred.join(", ") || "(none)"} — deferred work stays real, it is simply not next`
        : "value gate: NO runnable task serves an open exit criterion — the queue holds only deferrable debt, which is itself worth reporting",
    ],
    value_ordering: ordered,
    evaluated,
    binding: "STOP REFUSED — begin the next task.",
  };

  function term(condition, why, ev) {
    return {
      artifact: "continuation_decision",
      decision: "stop",
      terminal_condition: condition,
      next_task: null,
      reasons: [why],
      evaluated: ev,
      binding: "Stop permitted: a registered terminal condition holds.",
    };
  }
}

